//! The conformance vectors G1–G18 (`spaces-pallet.md` §10) and the mutation
//! lists, generated by running each scenario ([`scenarios`]) through the
//! mock over the golden fixtures, and committed under
//! `node/venue/conformance/`, which the verifier kit carries
//! (`vos_kit.py`'s `CONFORMANCE`).
//!
//! **A vector** is the chain's constants (the file's), a pre-state (the
//! time, the accounts, the pallet's raw storage) and steps, each at a time:
//! a call (its origin, its bytes as parts) or `on_idle`, and what it must
//! do: its result, the pallet's events in SCALE, its raw storage writes
//! (`null` a removal) and its balance deltas. A call's bytes are hex parts,
//! ranges of the kit's fixture files (`fixtures/wrap.proof`), so a proof is
//! not copied into the file once a submit, and runs of one byte. The file's
//! `unpinned` keys (`PruneCursor`'s) are left out of every step's storage.
//!
//! **Balances:** a pallet-level vector (`"fees": false`) pins every free
//! and held delta exactly, and a provider count's; a `fees` vector, Kreivo's
//! runtime with `ChargeSpaceFee`, pins free deltas by sign only, the
//! signer's always listed, and who paid the fee; its `Budget` writes are
//! pinned by key and `window`, their `spent`, which sums the fees, masked.

mod client;
mod mutations;
pub(super) mod scenarios;

use std::collections::{BTreeMap, BTreeSet};
use std::path::PathBuf;

use parity_scale_codec::{Decode, DecodeAll, Encode};
use serde::{Deserialize, Serialize};
use vos_statement::fixtures::{self, Patch};
use vos_statement::model::Input;
use vos_statement::{Statement, VenueId};

use super::mock::keys::{self, Item};
use super::mock::types::{
    Active, AnchorRecord, AuthorityInfo, DispatchError, Evidence, PALLET_INDEX, ProgramInfo,
    SpaceInfo, Spend,
};
use super::mock::{Account, Chain, Constants, Origin, Outcome, Payer, Verdict};

/// The vectors' directory, `node/venue/conformance`.
fn directory() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("conformance")
}

/// The vectors' file.
const SPACES: &str = "spaces.json";
/// The mutation lists' file.
const MUTATIONS: &str = "mutations.json";
/// Set to `write` to write the vectors instead of comparing them.
const MODE: &str = "VOS_CONFORMANCE";

pub fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

pub fn unhex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|at| u8::from_str_radix(&text[at..at + 2], 16).expect("hex"))
        .collect()
}

fn account_id(text: &str) -> [u8; 32] {
    unhex(text).try_into().expect("32 bytes")
}

/// The golden fixtures the vectors submit.
pub struct Fixtures {
    /// The fixtures' venue, the vectors' (a venue-bound program's
    /// statements name it).
    pub venue: VenueId,
    /// `S`, rooted at the fixture space, and `wrap.proof`.
    pub valid: Input,
    pub proof: Vec<u8>,
    /// `S0`, rootless, and `wrap-rootless.proof`.
    pub rootless: Input,
    pub rootless_proof: Vec<u8>,
    /// `wrap.proof` with a byte flipped, and its verdict.
    pub tampered: Vec<u8>,
    pub tampered_code: u32,
    /// The kit's fixture files a call's parts name.
    pub files: Vec<(String, Vec<u8>)>,
}

impl Fixtures {
    pub fn load() -> Self {
        let directory = fixtures::directory();
        let all = fixtures::load(&directory);
        let named = |name: &str| {
            all.iter()
                .find(|fixture| fixture.name == name)
                .unwrap_or_else(|| panic!("the fixture {name:?}"))
                .clone()
        };
        let (valid, rootless, tampered) = (named("valid"), named("rootless"), named("tampered"));
        let files = ["wrap.proof", "wrap-rootless.proof"]
            .map(|name| {
                let bytes = std::fs::read(directory.join(name)).expect("a fixture file");
                (name.to_string(), bytes)
            })
            .to_vec();
        assert_eq!(files[0].1, valid.proof);
        assert_eq!(files[1].1, rootless.proof);
        Self {
            venue: valid.input.policy.venue,
            valid: valid.input,
            proof: valid.proof,
            rootless: rootless.input,
            rootless_proof: rootless.proof,
            tampered: tampered.proof,
            tampered_code: tampered.verdict,
            files,
        }
    }

    pub fn statement(&self) -> &Statement {
        &self.valid.statement
    }
}

/// The vectors' file.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct File {
    pub about: Vec<String>,
    pub constants: ConstantsJson,
    /// Raw keys whose writes a harness leaves out of every step's storage:
    /// items the design lets a pallet keep that the mock does not
    /// (`PruneCursor`).
    pub unpinned: Vec<String>,
    /// Labels of the accounts and anchor keys the vectors use.
    pub names: BTreeMap<String, String>,
    pub vectors: Vec<Vector>,
}

