#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Vector {
    pub id: String,
    pub title: String,
    /// Kreivo's runtime with `ChargeSpaceFee`, not the pallet's mock
    /// runtime.
    pub fees: bool,
    pub pre: Pre,
    pub steps: Vec<Step>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Pre {
    pub now_ms: u64,
    pub accounts: Vec<AccountJson>,
    pub storage: Vec<Entry>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct AccountJson {
    pub account: String,
    pub free: String,
    pub held_registration: String,
    pub held_submit: String,
    pub providers: u32,
    pub consumers: u32,
}

/// A raw storage entry; `None` a removal.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Entry {
    pub key: String,
    pub value: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum OriginJson {
    Signed(#[serde(with = "account_hex")] [u8; 32]),
    Root,
    Programs,
    Emergency,
    Status,
}

mod account_hex {
    use serde::{Deserialize, Deserializer, Serializer};

    pub fn serialize<S: Serializer>(account: &[u8; 32], serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(&super::hex(account))
    }

    pub fn deserialize<'de, D: Deserializer<'de>>(deserializer: D) -> Result<[u8; 32], D::Error> {
        Ok(super::account_id(&String::deserialize(deserializer)?))
    }
}

impl From<Origin> for OriginJson {
    fn from(origin: Origin) -> Self {
        match origin {
            Origin::Signed(who) => Self::Signed(who),
            Origin::Root => Self::Root,
            Origin::Programs => Self::Programs,
            Origin::Emergency => Self::Emergency,
            Origin::Status => Self::Status,
        }
    }
}

impl From<OriginJson> for Origin {
    fn from(origin: OriginJson) -> Self {
        match origin {
            OriginJson::Signed(who) => Self::Signed(who),
            OriginJson::Root => Self::Root,
            OriginJson::Programs => Self::Programs,
            OriginJson::Emergency => Self::Emergency,
            OriginJson::Status => Self::Status,
        }
    }
}

/// A part of a call's bytes: hex, a range of a kit fixture file, or one
/// byte repeated.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Part {
    Hex(String),
    Fixture {
        fixture: String,
        from: usize,
        to: usize,
    },
    Repeat {
        /// The byte, in hex.
        repeat: String,
        count: usize,
    },
}

/// The shortest run of one byte a call's parts write as [`Part::Repeat`].
const RUN: usize = 256;

/// `bytes` as parts: hex, each run of [`RUN`] or more of one byte a repeat.
fn hex_parts(bytes: &[u8]) -> Vec<Part> {
    let mut out = Vec::new();
    let (mut at, mut plain) = (0, 0);
    while at < bytes.len() {
        let run = bytes[at..]
            .iter()
            .take_while(|byte| **byte == bytes[at])
            .count();
        if run >= RUN {
            if plain < at {
                out.push(Part::Hex(hex(&bytes[plain..at])));
            }
            out.push(Part::Repeat {
                repeat: hex(&[bytes[at]]),
                count: run,
            });
            plain = at + run;
        }
        at += run;
    }
    if plain < bytes.len() || out.is_empty() {
        out.push(Part::Hex(hex(&bytes[plain..])));
    }
    out
}

/// A call's result.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ResultJson {
    Ok,
    /// `DispatchError::Module { index: 90, error: [i, 0, 0, 0] }`.
    Module(u8),
    BadOrigin,
    /// `DispatchError::Token(FundsUnavailable)`.
    FundsUnavailable,
    /// `InvalidTransaction::Payment`, in `validate`: never included.
    InvalidPayment,
    /// The call's bytes do not decode: never included.
    Undecodable,
}

impl From<&Verdict> for ResultJson {
    fn from(verdict: &Verdict) -> Self {
        match verdict {
            Verdict::Ok => Self::Ok,
            Verdict::Err(DispatchError::Module(error)) => Self::Module(error.error[0]),
            Verdict::Err(DispatchError::BadOrigin) => Self::BadOrigin,
            Verdict::Err(DispatchError::Token(_)) => Self::FundsUnavailable,
            Verdict::Payment => Self::InvalidPayment,
            Verdict::Undecodable => Self::Undecodable,
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Step {
    pub now_ms: u64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub origin: Option<OriginJson>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub call: Option<Vec<Part>>,
    #[serde(default, skip_serializing_if = "std::ops::Not::not")]
    pub on_idle: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub result: Option<ResultJson>,
    pub events: Vec<String>,
    pub storage: Vec<Entry>,
    pub balances: Vec<Delta>,
    /// Who paid the fee, in a `fees` vector: `sovereign` or `signer`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub payer: Option<String>,
}

/// An account's balance deltas: exact (`+5`, `-5`), or by sign (`+`,
/// `-`, `0`) for a `fees` vector's free balance.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Delta {
    pub account: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub free: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub held_registration: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub held_submit: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub providers: Option<i64>,
}

fn delta(before: u128, after: u128) -> Option<String> {
    match after.cmp(&before) {
        std::cmp::Ordering::Equal => None,
        std::cmp::Ordering::Greater => Some(format!("+{}", after - before)),
        std::cmp::Ordering::Less => Some(format!("-{}", before - after)),
    }
}

fn sign(before: u128, after: u128) -> String {
    match after.cmp(&before) {
        std::cmp::Ordering::Equal => "0",
        std::cmp::Ordering::Greater => "+",
        std::cmp::Ordering::Less => "-",
    }
    .to_string()
}

/// A `Budget` value in a `fees` vector: its `window` in hex, its `spent`
/// (which sums the fees, the teammate's weights) `?` for each nibble.
fn masked_spend(value: &[u8]) -> String {
    let window = &value[..value.len().min(8)];
    format!(
        "{}{}",
        hex(window),
        "?".repeat(2 * value.len().saturating_sub(8))
    )
}

/// The pre-state of `chain`.
fn pre(chain: &Chain) -> Pre {
    Pre {
        now_ms: chain.now(),
        accounts: chain
            .accounts()
            .iter()
            .map(|(who, account)| AccountJson {
                account: hex(who),
                free: account.free.to_string(),
                held_registration: account.held_registration.to_string(),
                held_submit: account.held_submit.to_string(),
                providers: account.providers,
                consumers: account.consumers,
            })
            .collect(),
        storage: chain
            .storage()
            .iter()
            .map(|(key, value)| Entry {
                key: hex(key),
                value: Some(hex(value)),
            })
            .collect(),
    }
}

/// A chain in `pre`'s state.
fn load(constants: &Constants, fees: bool, pre: &Pre) -> Chain {
    let mut chain = Chain::new(constants.clone()).with_fees(fees);
    chain.set_now(pre.now_ms);
    for account in &pre.accounts {
        chain.set_account(
            account_id(&account.account),
            Account {
                free: account.free.parse().expect("a balance"),
                held_registration: account.held_registration.parse().expect("a balance"),
                held_submit: account.held_submit.parse().expect("a balance"),
                providers: account.providers,
                consumers: account.consumers,
            },
        );
    }
    for entry in &pre.storage {
        chain.set_storage(
            unhex(&entry.key),
            unhex(entry.value.as_ref().expect("a value")),
        );
    }
    chain
}

/// What a step did, from the chain before and after it.
fn step(
    before: &Chain,
    after: &Chain,
    origin: Option<Origin>,
    call: Option<Vec<Part>>,
    outcome: Option<&Outcome>,
) -> Step {
    let fees = after.fees();
    let budget = Item::Budget.prefix();
    let keys: BTreeSet<&Vec<u8>> = before
        .storage()
        .keys()
        .chain(after.storage().keys())
        .collect();
    let storage = keys
        .into_iter()
        .filter_map(|key| {
            let (was, is) = (before.storage().get(key), after.storage().get(key));
            let value = |value: &Vec<u8>| match fees && key.starts_with(&budget) {
                true => masked_spend(value),
                false => hex(value),
            };
            let changed = match fees && key.starts_with(&budget) {
                true => was.map(value) != is.map(value),
                false => was != is,
            };
            changed.then(|| Entry {
                key: hex(key),
                value: is.map(value),
            })
        })
        .collect();
    let signer = match origin {
        Some(Origin::Signed(who)) => Some(who),
        _ => None,
    };
    let accounts: BTreeSet<&[u8; 32]> = before
        .accounts()
        .keys()
        .chain(after.accounts().keys())
        .chain(signer.as_ref())
        .collect();
    let balances = accounts
        .into_iter()
        .filter_map(|who| {
            let (was, is) = (before.account(who), after.account(who));
            let free = if fees {
                let changed = was.free != is.free || signer.as_ref() == Some(who);
                changed.then(|| sign(was.free, is.free))
            } else {
                delta(was.free, is.free)
            };
            let entry = Delta {
                account: hex(who),
                free,
                held_registration: delta(was.held_registration, is.held_registration),
                held_submit: delta(was.held_submit, is.held_submit),
                providers: Some(i64::from(is.providers) - i64::from(was.providers))
                    .filter(|change| *change != 0),
            };
            let moved = entry.free.is_some()
                || entry.held_registration.is_some()
                || entry.held_submit.is_some()
                || entry.providers.is_some();
            moved.then_some(entry)
        })
        .collect();
    Step {
        now_ms: after.now(),
        origin: origin.map(OriginJson::from),
        on_idle: call.is_none(),
        call,
        result: outcome.map(|outcome| ResultJson::from(&outcome.verdict)),
        events: outcome
            .map(|outcome| {
                outcome
                    .events
                    .iter()
                    .map(|event| hex(&event.encode()))
                    .collect()
            })
            .unwrap_or_default(),
        storage,
        balances,
        payer: outcome.and_then(|outcome| outcome.payer).map(|payer| {
            match payer {
                Payer::Sovereign => "sovereign",
                Payer::Signer => "signer",
            }
            .to_string()
        }),
    }
}

/// A call's bytes as parts: a proof at its tail, equal to a fixture file
/// but for a few bytes, a range of that file around them.
fn parts(bytes: &[u8], files: &[(String, Vec<u8>)]) -> Vec<Part> {
    for (name, file) in files {
        let Some(start) = bytes.len().checked_sub(file.len()) else {
            continue;
        };
        let patch = Patch::between(file, &bytes[start..]);
        if patch.removed as usize + patch.inserted.len() > 64 {
            continue;
        }
        let (offset, removed) = (patch.offset as usize, patch.removed as usize);
        let range = |from: usize, to: usize| {
            (from < to).then(|| Part::Fixture {
                fixture: name.clone(),
                from,
                to,
            })
        };
        return hex_parts(&bytes[..start])
            .into_iter()
            .chain(
                [
                    range(0, offset),
                    (!patch.inserted.is_empty()).then(|| Part::Hex(hex(&patch.inserted))),
                    range(offset + removed, file.len()),
                ]
                .into_iter()
                .flatten(),
            )
            .collect();
    }
    hex_parts(bytes)
}

/// The bytes `parts` name.
fn assemble(parts: &[Part], files: &[(String, Vec<u8>)]) -> Vec<u8> {
    parts
        .iter()
        .flat_map(|part| match part {
            Part::Hex(text) => unhex(text),
            Part::Fixture { fixture, from, to } => {
                let (_, file) = files
                    .iter()
                    .find(|(name, _)| name == fixture)
                    .unwrap_or_else(|| panic!("the fixture file {fixture}"));
                file[*from..*to].to_vec()
            }
            Part::Repeat { repeat, count } => unhex(repeat).repeat(*count),
        })
        .collect()
}

/// The files' contents: the vectors' JSON and the mutation lists', each
/// with a final newline.
fn generate() -> [(&'static str, String); 2] {
    let fixtures = Fixtures::load();
    let file = scenarios::file(&fixtures);
    let json = |value: String| value + "\n";
    [
        (
            SPACES,
            json(serde_json::to_string_pretty(&file).expect("serializes")),
        ),
        (
            MUTATIONS,
            json(serde_json::to_string_pretty(&mutations::lists(&fixtures)).expect("serializes")),
        ),
    ]
}

/// Each vector replayed on a fresh mock from its JSON: its pre-state
/// loaded, each step run, and what it did the step's expectation.
/// Whether `T` decodes all of `value`.
fn decodes<T: Decode>(value: &[u8]) -> bool {
    T::decode_all(&mut &value[..]).is_ok()
}

/// An entry checked as its item's: the key's length its hashers' (after
/// the 32-byte prefix), the value its type's, whole.
fn typed(entry: &Entry) {
    let key = unhex(&entry.key);
    let items = [
        (Item::Spaces, 32, decodes::<SpaceInfo> as fn(&[u8]) -> bool),
        (Item::SovereignOf, 16 + 32, decodes::<[u8; 32]>),
        (Item::Authorities, 32 + 16 + 32, decodes::<AuthorityInfo>),
        (Item::AnchorKeys, 32 + 32, decodes::<Option<[u8; 32]>>),
        (Item::Anchors, 32 + 9 + 16, decodes::<AnchorRecord>),
        (Item::Last, 32 + 9, decodes::<u64>),
        (Item::Equivocations, 32 + 9 + 16, decodes::<Evidence>),
        (Item::Budget, 32, decodes::<Spend>),
        (Item::Formats, 8 + 4, decodes::<Active>),
        (Item::Programs, 16 + 32, decodes::<ProgramInfo>),
        (Item::Seen, 32, decodes::<u64>),
        (Item::Paused, 0, decodes::<u8>),
    ];
    let (item, parts, decode) = items
        .into_iter()
        .find(|(item, ..)| key.starts_with(&item.prefix()))
        .unwrap_or_else(|| panic!("{}: no item's key", entry.key));
    assert_eq!(key.len(), 32 + parts, "{}: {item:?}'s key", entry.key);
    if let Some(value) = entry.value.as_ref().filter(|value| value.contains('?')) {
        assert_eq!(item, Item::Budget, "{}: masked", entry.key);
        assert_eq!(value.len(), 2 * (8 + 16), "{}: a Spend", entry.key);
        assert!(value[..16].bytes().all(|nibble| nibble.is_ascii_hexdigit()));
        return;
    }
    if let Some(value) = &entry.value {
        assert!(
            decode(&unhex(value)),
            "{}: {item:?}'s value {value}",
            entry.key
        );
    }
}

fn replay(file: &File, fixtures: &Fixtures) {
    replay_on(file, fixtures, |chain| chain);
}

/// [`replay`] on the chain `pallet` makes of each vector's pre-state.
fn replay_on(file: &File, fixtures: &Fixtures, pallet: impl Fn(Chain) -> Chain) {
    let constants = Constants::kreivo(fixtures.venue);
    assert_eq!(file.constants, ConstantsJson::of(&constants));
    for vector in &file.vectors {
        vector.pre.storage.iter().for_each(typed);
        for step in &vector.steps {
            step.storage.iter().for_each(typed);
        }
        let mut chain = pallet(load(&constants, vector.fees, &vector.pre));
        for (n, expected) in vector.steps.iter().enumerate() {
            let before = chain.clone();
            chain.set_now(expected.now_ms);
            let done = match (&expected.call, expected.origin) {
                (Some(parts), Some(origin)) => {
                    let bytes = assemble(parts, &fixtures.files);
                    let outcome = chain.submit(origin.into(), &bytes);
                    step(
                        &before,
                        &chain,
                        Some(origin.into()),
                        Some(parts.clone()),
                        Some(&outcome),
                    )
                }
                _ => {
                    assert!(
                        expected.on_idle,
                        "{} step {n}: a call or on_idle",
                        vector.id
                    );
                    chain.on_idle();
                    step(&before, &chain, None, None, None)
                }
            };
            assert_eq!(&done, expected, "{} step {n}", vector.id);
        }
    }
}

/// The mock passes G1–G18: each vector, read from the committed file and
/// replayed on a fresh mock, does what it says.
#[test]
fn the_mock_passes_every_vector() {
    let fixtures = Fixtures::load();
    let text = std::fs::read_to_string(directory().join(SPACES)).expect("the vectors");
    let file: File = serde_json::from_str(&text).expect("the vectors parse");
    let ids: Vec<&str> = file
        .vectors
        .iter()
        .map(|vector| vector.id.as_str())
        .collect();
    let expected: Vec<String> = (1..=18).map(|n| format!("G{n}")).collect();
    assert_eq!(ids, expected);
    replay(&file, &fixtures);
}

/// The committed vectors, as a pallet's harness reads them.
fn committed() -> File {
    let text = std::fs::read_to_string(directory().join(SPACES)).expect("the vectors");
    serde_json::from_str(&text).expect("the vectors parse")
}

/// Whether vector `id` replayed on the chain `pallet` makes passes.
fn passes(id: &str, pallet: impl Fn(Chain) -> Chain) -> bool {
    let fixtures = Fixtures::load();
    let mut file = committed();
    file.vectors.retain(|vector| vector.id == id);
    assert_eq!(file.vectors.len(), 1, "{id}");
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        replay_on(&file, &fixtures, pallet)
    }))
    .is_ok()
}

/// Pallets the vectors must fail, each broken one way: one that takes
/// every stored format and program as active, whatever its window (G7
/// submits against a format not yet active, and a program past its
/// `until_ms` and before its `from_ms`); one with other length bounds (G18
/// submits at each bound and a byte past it); one that does not credit an
/// accepted submit's deposit back to its window's budget (G13).
#[test]
fn a_broken_pallet_fails_the_vectors() {
    use super::mock::Broken;
    assert!(passes("G7", |chain| chain));
    assert!(!passes("G7", |chain| chain.broken(Broken::Activation)));
    assert!(passes("G18", |chain| chain));
    for widen in [
        |bounds: &mut super::mock::types::Bounds| bounds.genesis += 1,
        |bounds: &mut super::mock::types::Bounds| bounds.statement += 1,
        |bounds: &mut super::mock::types::Bounds| bounds.proof += 1,
    ] {
        assert!(!passes("G18", |mut chain| {
            widen(&mut chain.constants.bounds);
            chain
        }));
    }
    assert!(passes("G13", |chain| chain));
    assert!(!passes("G13", |chain| chain.broken(Broken::CreditBack)));
}

/// The file names `PruneCursor`'s key, which a pallet may keep for
/// `on_idle` (`spaces-pallet.md` §5) and the mock does not, as unpinned.
#[test]
fn the_prune_cursor_is_unpinned() {
    let cursor = [keys::twox128(keys::PALLET), keys::twox128(b"PruneCursor")].concat();
    assert_eq!(committed().unpinned, [hex(&cursor)]);
}

/// The committed vectors and mutation lists are the generator's, byte for
/// byte; `just conformance` writes them anew.
#[test]
fn the_vectors_are_the_generators() {
    let write = std::env::var(MODE).is_ok_and(|mode| mode == "write");
    for (name, content) in generate() {
        let path = directory().join(name);
        if write {
            std::fs::create_dir_all(directory()).expect("the directory");
            std::fs::write(&path, &content).expect("writes");
            continue;
        }
        let committed = std::fs::read_to_string(&path).unwrap_or_else(|error| {
            panic!("{}: {error}; `just conformance` writes it", path.display())
        });
        assert!(
            committed == content,
            "{} is stale: `just conformance` writes it anew",
            path.display()
        );
    }
}
